?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Search Console SEO | TechSelectAI</title><style>body{font-family:system-ui;margin:0;background:#f6f8fb;color:#1f2937}.wrap{max-width:1280px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:16px;align-items:center;flex-wrap:wrap}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}.card,.panel{background:#fff;border:1px solid #dde5ee;border-radius:14px;padding:16px}.kpi{font-size:28px;font-weight:800}.muted{color:#64748b;font-size:13px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.tablewrap{overflow:auto}.table{width:100%;border-collapse:collapse;font-size:13px}.table th,.table td{padding:8px;border-bottom:1px solid #edf2f7;text-align:left}.table th{cursor:pointer;white-space:nowrap}.controls{display:flex;gap:8px;flex-wrap:wrap}input,select,textarea,button{font:inherit}.controls input,.controls select{padding:8px;border:1px solid #cfd8e3;border-radius:8px}button.primary{background:#123b67;color:#fff;border:0;padding:9px 14px;border-radius:9px}.chart{display:flex;align-items:flex-end;gap:3px;height:120px;padding-top:10px}.chart i{flex:1;min-width:2px;background:#64748b;border-radius:2px 2px 0 0}.wide{grid-column:1/-1}.buckets{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.bucket{padding:12px;border:1px solid #e2e8f0;border-radius:10px}.bucket strong{font-size:22px;display:block}.links a{margin-right:14px}@media(max-width:800px){.cards,.grid{grid-template-columns:1fr 1fr}.buckets{grid-template-columns:1fr 1fr}}@media(max-width:560px){.cards,.grid,.buckets{grid-template-columns:1fr}}</style></head><body><div class="wrap"><div class="top"><div><h1>Google Search Console SEO</h1><div class="muted" id="refresh">Data source: not loaded</div><div class="links muted"><a href="/indexation-health">Indexation health</a></div></div><div class="controls"><select id="days"><option value="7">7 days</option><option value="28" selected>28 days</option><option value="90">90 days</option></select><button class="primary" id="reload">Refresh</button><button id="export">Export CSV</button></div></div><div class="cards"><div class="card"><div class="muted">Clicks</div><div class="kpi" id="clicks">0</div><div class="muted" id="clickDelta"></div></div><div class="card"><div class="muted">Impressions</div><div class="kpi" id="impressions">0</div><div class="muted" id="imprDelta"></div></div><div class="card"><div class="muted">CTR</div><div class="kpi" id="ctr">0%</div></div><div class="card"><div class="muted">Avg position</div><div class="kpi" id="position">0</div></div></div><div class="panel wide"><h2>Query position distribution</h2><div class="buckets"><div class="bucket"><span class="muted">Top 10</span><strong id="b10">0</strong></div><div class="bucket"><span class="muted">11–20</span><strong id="b20">0</strong></div><div class="bucket"><span class="muted">21–50</span><strong id="b50">0</strong></div><div class="bucket"><span class="muted">Beyond 50</span><strong id="beyond">0</strong></div></div></div><div class="panel wide"><h2>Impression trend</h2><div class="chart" id="chart"></div></div><div class="grid"><div class="panel"><h2>Quick wins: positions 11–30</h2><div id="wins" class="tablewrap"></div></div><div class="panel"><h2>High impressions, low CTR</h2><div id="lowctr" class="tablewrap"></div></div><div class="panel"><h2>Pages gaining visibility</h2><div id="gains" class="tablewrap"></div></div><div class="panel"><h2>Declining pages</h2><div id="declines" class="tablewrap"></div></div><div class="panel"><h2>New queries</h2><div id="newq" class="tablewrap"></div></div><div class="panel"><h2>Import Search Console rows</h2><p class="muted">Initial integration supports controlled manual/scheduled JSON import from Google Search Console exports/API output. Rows can include date, query, page, country, device, search_appearance, clicks, impressions, ctr and position.</p><div class="controls"><input id="from" type="date"><input id="to" type="date"><input id="property" placeholder="Property URI"></div><textarea id="payload" rows="8" style="width:100%;margin-top:8px" placeholder='[{"date":"2026-09-01","query":"crm software saudi","page":"https://techselectai.com/software/example","clicks":2,"impressions":100,"ctr":0.02,"position":14.2}]'></textarea><button class="primary" id="importBtn">Import</button><div class="muted" id="importMsg"></div></div><div class="panel wide"><h2>Top queries</h2><div id="queries" class="tablewrap"></div></div><div class="panel wide"><h2>Top pages</h2><div id="pages" class="tablewrap"></div></div><div class="panel"><h2>Countries</h2><div id="countries" class="tablewrap"></div></div><div class="panel"><h2>Devices</h2><div id="devices" class="tablewrap"></div></div><div class="panel wide"><h2>Search appearance</h2><div id="appearances" class="tablewrap"></div></div></div></div><script>let data=null,csrf='',tableSeq=0;const n=v=>Number(v||0),pct=v=>(n(v)*100).toFixed(1)+'%',fmt=v=>Math.round(n(v)).toLocaleString(),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])),delta=(a,b)=>{a=n(a);b=n(b);if(!b)return a?'new':'0%';return ((a-b)/b*100).toFixed(1)+'% vs previous';};function normalize(r){return{name:r.dimension??r.query??r.page??'',clicks:n(r.clicks??r.current_clicks),impressions:n(r.impressions??r.current_impressions),ctr:n(r.ctr),position:n(r.position),previous:n(r.previous_impressions)}}function table(rows,label,comparison=false){if(!rows?.length)return '<div class="muted">No data</div>';const id='t'+(++tableSeq),norm=rows.map(normalize);let html='<table class="table" id="'+id+'"><thead><tr><th data-k="name">'+label+'</th><th data-k="clicks">Clicks</th><th data-k="impressions">Impr.</th>'+(comparison?'<th data-k="previous">Prev. impr.</th>':'<th data-k="ctr">CTR</th><th data-k="position">Pos.</th>')+'</tr></thead><tbody>'+norm.map(r=>'<tr><td>'+esc(r.name)+'</td><td data-v="'+r.clicks+'">'+fmt(r.clicks)+'</td><td data-v="'+r.impressions+'">'+fmt(r.impressions)+'</td>'+(comparison?'<td data-v="'+r.previous+'">'+fmt(r.previous)+'</td>':'<td data-v="'+r.ctr+'">'+pct(r.ctr)+'</td><td data-v="'+r.position+'">'+r.position.toFixed(1)+'</td>')+'</tr>').join('')+'</tbody></table>';setTimeout(()=>wireSort(id),0);return html;}function wireSort(id){const t=document.getElementById(id);if(!t)return;t.querySelectorAll('th').forEach((th,idx)=>th.onclick=()=>{const rows=[...t.tBodies[0].rows],asc=th.dataset.asc!=='1';rows.sort((a,b)=>{let av=idx?Number(a.cells[idx].dataset.v||0):a.cells[idx].textContent.toLowerCase(),bv=idx?Number(b.cells[idx].dataset.v||0):b.cells[idx].textContent.toLowerCase();return(av>bv?1:av<bv?-1:0)*(asc?1:-1)});rows.forEach(r=>t.tBodies[0].appendChild(r));th.dataset.asc=asc?'1':'0';});});}async function load(){const days=document.getElementById('days').value;const r=await fetch('/api/search-console?days='+days,{credentials:'same-origin'}),j=await r.json();if(!r.ok){alert(j.error||'Load failed');return;}data=j;csrf=j.csrf_token||csrf;clicks.textContent=fmt(j.summary.clicks);impressions.textContent=fmt(j.summary.impressions);ctr.textContent=pct(j.summary.ctr);position.textContent=n(j.summary.position).toFixed(1);clickDelta.textContent=delta(j.summary.clicks,j.previous_summary.clicks);imprDelta.textContent=delta(j.summary.impressions,j.previous_summary.impressions);refresh.textContent=j.last_refresh?'Data source: '+j.last_refresh.source_label+' · property '+(j.last_refresh.property_uri||'not specified')+' · refreshed '+j.last_refresh.imported_at:'Data source: no Search Console import yet';b10.textContent=fmt(j.position_buckets.top10);b20.textContent=fmt(j.position_buckets.top20);b50.textContent=fmt(j.position_buckets.top50);beyond.textContent=fmt(j.position_buckets.beyond50);queries.innerHTML=table(j.queries,'Query');pages.innerHTML=table(j.pages,'Page');wins.innerHTML=table(j.quick_wins,'Query');lowctr.innerHTML=table(j.low_ctr_pages,'Page');gains.innerHTML=table(j.gaining_pages,'Page',true);declines.innerHTML=table(j.declining_pages,'Page',true);newq.innerHTML=table(j.new_queries,'Query');countries.innerHTML=table(j.countries,'Country');devices.innerHTML=table(j.devices,'Device');appearances.innerHTML=table(j.appearances,'Appearance');const max=Math.max(1,...j.daily.map(x=>n(x.impressions)));chart.innerHTML=j.daily.map(x=>'<i title="'+x.date+' · '+fmt(x.impressions)+' impressions" style="height:'+Math.max(2,n(x.impressions)/max*100)+'%"></i>').join('');}reload.onclick=load;days.onchange=load;importBtn.onclick=async()=>{let rows;try{rows=JSON.parse(payload.value)}catch(e){importMsg.textContent='Invalid JSON';return;}const body={source_label:'google_search_console_manual',property_uri:property.value,date_from:from.value,date_to:to.value,rows};const r=await fetch('/api/search-console/import',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)}),j=await r.json();importMsg.textContent=r.ok?'Imported '+j.rows_imported+' rows':(j.error||'Import failed');if(r.ok)load();};export.onclick=()=>{if(!data)return;const rows=[['type','name','clicks','impressions','ctr','position'],...data.queries.map(r=>['query',r.dimension,r.clicks,r.impressions,r.ctr,r.position]),...data.pages.map(r=>['page',r.dimension,r.clicks,r.impressions,r.ctr,r.position])];const csv=rows.map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='techselectai-search-console.csv';a.click();URL.revokeObjectURL(a.href);};load();</script></body></html>